<?php
declare(strict_types=1);
function ndProviderMap(array $item, string $anchor = ''): string
{
    $points = []; $missing = 0;
    $specialties = [];
    $doctorIds = array_values(array_unique(array_filter(array_map(static fn($provider) => (int)($provider['dr_id'] ?? 0), $item['providers']))));
    if ($doctorIds) {
        foreach (lcnNdRows(lcnTreatmentsNdDatabase(), 'SELECT lcn_id, fachrichtung FROM tbl_fachrichtungen_nd WHERE lcn_id IN (' . implode(',', array_fill(0, count($doctorIds), '?')) . ') ORDER BY fachrichtung', $doctorIds) as $row) {
            $specialties[(int)$row['lcn_id']][] = $row['fachrichtung'];
        }
    }
    foreach ($item['providers'] as $provider) {
        if ($provider['relation_status'] === 'kandidat') continue;
        if (!is_numeric($provider['loc_lat']) || !is_numeric($provider['loc_lng']) || abs((float)$provider['loc_lat']) > 90 || abs((float)$provider['loc_lng']) > 180 || ((float)$provider['loc_lat'] === 0.0 && (float)$provider['loc_lng'] === 0.0)) { $missing++; }
        $points[] = ['specialties'=>$specialties[(int)($provider['dr_id'] ?? 0)] ?? [],'dr_id'=>(int)($provider['dr_id'] ?? 0),'lat' => is_numeric($provider['loc_lat']) ? (float)$provider['loc_lat'] : null, 'lng' => is_numeric($provider['loc_lng']) ? (float)$provider['loc_lng'] : null, 'name' => $provider['name'], 'href' => $provider['dr_id'] && lcnDoctorExists((int)$provider['dr_id']) ? 'arzt_detail.html?id=' . (int)$provider['dr_id'] : null, 'city' => trim((string)$provider['loc_city']), 'place' => trim($provider['loc_plz'] . ' ' . $provider['loc_city']), 'status' => $provider['relation_status'] === 'belegt' ? 'Angebot belegt' : 'Übernommene Bestandszuordnung'];
    }
    static $instance = 0;
    $mapId = 'nd-provider-map-' . ++$instance;
    $json = json_encode($points, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_UNESCAPED_UNICODE);
    return ndCard('Standorte', '<div class="nd-provider-map" data-independent-at-home="'.(lcnNdIndependentAtHome($item)?'1':'0').'"><div class="top-map-location-controls"><h4 class="nd-location-title">Standortsuche</h4><form class="nd-map-location"><div class="nd-location-heading"><label for="' . $mapId . '-input">Adresse, PLZ oder Ort</label><button type="button" data-map-clear class="is-hidden" aria-label="Gespeicherten Standort entfernen">×</button></div><div class="top-map-location-input-row"><input id="' . $mapId . '-input" name="location" maxlength="200" placeholder="z. B. 50667 oder Köln" autocomplete="off"><div class="top-map-location-suggestions is-hidden"></div></div><button type="submit" class="nd-location-submit">Standort übernehmen</button></form><div class="nd-location-mode-switch" aria-label="Suchmodus"><button type="button" data-location-mode="radius" aria-pressed="true">Radius</button><button type="button" data-location-mode="city" aria-pressed="false">Ort</button></div><div class="nd-location-filters"><div class="nd-radius-inline" data-location-radius-controls><label class="nd-radius-value"><span>Radius in Kilometern</span><input type="number" data-radius min="1" max="2000" step="1" value="100" aria-label="Radius in Kilometern"></label><label class="nd-radius-toggle"><input type="checkbox" role="switch" data-radius-enabled aria-label="Radius aktivieren"> Radius aktivieren</label><label class="nd-include-unlocated"><input type="checkbox" data-include-no-coords> Einträge ohne Koordinaten einbeziehen</label></div><label data-location-city-controls>Ort auswählen<select data-provider-city><option value="">Alle Städte</option></select></label><p data-location-filter-note role="status"></p></div><div class="nd-location-summary"><strong data-location-provider-count role="status"></strong><span>Behandler im Filter</span></div></div><div class="top-map-panel"><div id="' . $mapId . '-content" class="top-map-content"><div class="nd-map-canvas" aria-label="Karte der Behandler"></div><p class="top-map-status" data-map-status role="status">Standorte werden geladen …</p></div></div><section class="doctor-results-panel"><div class="doctor-results-header"><span class="doctor-results-header-left">▤ Behandler</span><div class="doctor-view-switch doctor-view-switch-in-header" aria-label="Behandleransicht wechseln"><button type="button" class="doctor-view-switch-button is-active" data-provider-view="cards" aria-pressed="true">Kacheln</button><button type="button" class="doctor-view-switch-button" data-provider-view="table" aria-pressed="false">Tabelle</button></div></div><div class="doctor-results-search-panel"><div class="doctor-results-search-row"><label class="doctor-results-search-field"><span class="doctor-results-search-label">Behandler suchen</span><input type="search" class="doctor-results-search-input" data-provider-search placeholder="Name oder Ort eingeben"></label><label class="doctor-results-sort-field"><span class="doctor-results-search-label">Sortieren nach</span><select class="doctor-results-search-input" data-provider-sort><option value="name:asc">Name A–Z</option><option value="name:desc">Name Z–A</option><option value="distance:asc">Entfernung ↑</option><option value="distance:desc">Entfernung ↓</option></select></label></div></div><p data-provider-count role="status"></p><div class="nd-map-results"></div></section>' . ($missing ? '<p>Bei ' . $missing . ' Behandlern ist der Kartenstandort nicht verfügbar.</p>' : '') . '<script type="application/json" class="nd-map-data">' . $json . '</script></div>', $anchor);
}

